/**
 * TASK: Implement rubber-band (drag rectangle) selection.
 *
 * Five dots sit at fixed positions. A drag selects every dot inside the
 * rectangle spanned by the press point and the current drag point.
 *
 * Register a MouseListener and a MouseMotionListener so that:
 *   mousePressed  -- anchors the rectangle at (e.getX(), e.getY()) and makes
 *                    the current point the same, so the rectangle is empty
 *   mouseDragged  -- moves the current point to (e.getX(), e.getY())
 *   mouseReleased -- moves the current point one last time, then fills the
 *                    selected list with the NAMES of the dots inside the
 *                    rectangle (in the order the dots are declared) and sets
 *                    the label named "selected" to "<n> selected"
 *
 * Then complete selectionBounds(): a java.awt.Rectangle whose x/y is the
 * TOP-LEFT corner and whose width/height are never negative -- the user may
 * drag up and to the left, so use the smaller coordinate as the corner and
 * the absolute difference as the size.
 *
 * Example: press at (80, 90) and drag to (30, 20) -> the bounds are
 * x=30, y=20, width=50, height=70.
 *
 * A dot exactly on an edge or corner of the rectangle COUNTS as selected, so
 * compare coordinates yourself (x >= left && x <= right) instead of using
 * Rectangle.contains, which treats the right and bottom edges as outside.
 *
 * No window is ever opened -- the tests build MouseEvents by hand and hand
 * them to the panel with dispatchEvent.
 */
import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class RubberBandSelector extends JPanel {

    private static final String[] DOT_NAMES = { "A", "B", "C", "D", "E" };
    private static final int[] DOT_X = { 20, 45, 100, 50, 0 };
    private static final int[] DOT_Y = { 20, 35, 100, 40, 0 };

    private final JLabel selectedLabel = new JLabel("0 selected");
    private final List<String> selected = new ArrayList<>();
    private int anchorX = 0;
    private int anchorY = 0;
    private int currentX = 0;
    private int currentY = 0;

    public RubberBandSelector() {
        selectedLabel.setName("selected");
        add(selectedLabel);
        // TODO: addMouseListener(...) for mousePressed and mouseReleased
        // TODO: addMouseMotionListener(...) for mouseDragged
    }

    public Rectangle selectionBounds() {
        // TODO: build the normalised rectangle from the anchor and current point
        return new Rectangle();
    }

    public List<String> selectedNames() {
        return new ArrayList<>(selected);
    }

    public int selectedCount() {
        return selected.size();
    }

    static String[] dotNames() {
        return DOT_NAMES;
    }
}

