public class RubberBandSelectorTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String textOf(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        if (c instanceof javax.swing.text.JTextComponent) {
            return ((javax.swing.text.JTextComponent) c).getText();
        }
        return "(missing)";
    }

    static void send(RubberBandSelector panel, int id, int x, int y) {
        panel.dispatchEvent(new java.awt.event.MouseEvent(panel, id,
                System.currentTimeMillis(), 0, x, y, 1, false));
    }

    static void press(RubberBandSelector panel, int x, int y) {
        send(panel, java.awt.event.MouseEvent.MOUSE_PRESSED, x, y);
    }

    static void drag(RubberBandSelector panel, int x, int y) {
        send(panel, java.awt.event.MouseEvent.MOUSE_DRAGGED, x, y);
    }

    static void release(RubberBandSelector panel, int x, int y) {
        send(panel, java.awt.event.MouseEvent.MOUSE_RELEASED, x, y);
    }

    static String rect(java.awt.Rectangle r) {
        if (r == null) {
            return "null";
        }
        return r.x + "," + r.y + "," + r.width + "," + r.height;
    }

    public static void main(String[] args) {
        try {
            RubberBandSelector panel = new RubberBandSelector();
            java.awt.Component label = find(panel, "selected");

            check("a MouseMotionListener is registered", true,
                    panel.getMouseMotionListeners().length >= 1);

            press(panel, 10, 10);
            check("a fresh press spans nothing", "10,10,0,0", rect(panel.selectionBounds()));

            drag(panel, 50, 40);
            check("bounds while dragging right and down", "10,10,40,30",
                    rect(panel.selectionBounds()));

            release(panel, 50, 40);
            check("dots inside the band", "[A, B, D]", panel.selectedNames().toString());
            check("label after the first drag", "3 selected", textOf(label));

            press(panel, 80, 90);
            drag(panel, 30, 20);
            check("dragging up and left still gives a positive size", "30,20,50,70",
                    rect(panel.selectionBounds()));
            release(panel, 30, 20);
            check("dots inside the backwards band", "[B, D]",
                    panel.selectedNames().toString());

            press(panel, 200, 200);
            drag(panel, 240, 240);
            release(panel, 240, 240);
            check("an empty region selects nothing", 0, panel.selectedCount());
            check("label after selecting nothing", "0 selected", textOf(label));
        } catch (Throwable t) {
            System.out.println("FAIL  unexpected problem -- " + t);
            failures++;
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

