import java.awt.Rectangle;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class RubberBandSelector extends JPanel {

    private static final String[] DOT_NAMES = { "A", "B", "C", "D", "E" };
    private static final int[] DOT_X = { 20, 45, 100, 50, 0 };
    private static final int[] DOT_Y = { 20, 35, 100, 40, 0 };

    private final JLabel selectedLabel = new JLabel("0 selected");
    private final List<String> selected = new ArrayList<>();
    private int anchorX = 0;
    private int anchorY = 0;
    private int currentX = 0;
    private int currentY = 0;

    public RubberBandSelector() {
        selectedLabel.setName("selected");
        add(selectedLabel);
        addMouseListener(new MouseAdapter() {
            @Override
            public void mousePressed(MouseEvent e) {
                anchorX = e.getX();
                anchorY = e.getY();
                currentX = anchorX;
                currentY = anchorY;
            }

            @Override
            public void mouseReleased(MouseEvent e) {
                currentX = e.getX();
                currentY = e.getY();
                collect();
            }
        });
        addMouseMotionListener(new MouseAdapter() {
            @Override
            public void mouseDragged(MouseEvent e) {
                currentX = e.getX();
                currentY = e.getY();
            }
        });
    }

    private void collect() {
        Rectangle bounds = selectionBounds();
        int left = bounds.x;
        int top = bounds.y;
        int right = bounds.x + bounds.width;
        int bottom = bounds.y + bounds.height;
        selected.clear();
        for (int i = 0; i < DOT_NAMES.length; i++) {
            if (DOT_X[i] >= left && DOT_X[i] <= right
                    && DOT_Y[i] >= top && DOT_Y[i] <= bottom) {
                selected.add(DOT_NAMES[i]);
            }
        }
        selectedLabel.setText(selected.size() + " selected");
    }

    public Rectangle selectionBounds() {
        int x = Math.min(anchorX, currentX);
        int y = Math.min(anchorY, currentY);
        int width = Math.abs(currentX - anchorX);
        int height = Math.abs(currentY - anchorY);
        return new Rectangle(x, y, width, height);
    }

    public List<String> selectedNames() {
        return new ArrayList<>(selected);
    }

    public int selectedCount() {
        return selected.size();
    }

    static String[] dotNames() {
        return DOT_NAMES;
    }
}
